package com.networkers.eventfee;import com.networkers.user.User;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;public interface EventFeeRepository extends JpaRepository<EventFee,Long>{Optional<EventFee> findByUserAndYearAndMonth(User user,int year,int month);List<EventFee> findByYearAndMonthOrderByUserFullNameAsc(int year,int month);List<EventFee> findByYearAndMonthAndStatus(int year,int month,EventFeeStatus status);}
